"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["2152"],{85902(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>l,frontMatter:()=>c,contentTitle:()=>d,toc:()=>u,assets:()=>h});var i=JSON.parse('{"id":"nhcx/v1/api/communication/endpoints/communication-internal-v1-communication-request","title":"Submit the communication request (internal variant) (adapter)","description":"Internal twin of /v1/communication/request: same JWEPayload body, description and 202 envelope, operationId communicationRequestPostInternal.","source":"@site/docs/nhcx/v1/api/communication/endpoints/communication-internal-v1-communication-request.mdx","sourceDirName":"nhcx/v1/api/communication/endpoints","slug":"/nhcx/v1/api/communication/endpoints/communication-internal-v1-communication-request","permalink":"/docs/pr-20/docs/nhcx/v1/api/communication/endpoints/communication-internal-v1-communication-request","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the communication request (internal variant) (adapter)","sidebar_label":"Submit the communication request (internal variant) (adapter)","sidebar_class_name":"api-method api-method--post","description":"Internal twin of /v1/communication/request: same JWEPayload body, description and 202 envelope, operationId communicationRequestPostInternal.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-communication.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Submit the communication acknowledgement callback","permalink":"/docs/pr-20/docs/nhcx/v1/api/communication/endpoints/communication-v1-communication-on-request"},"next":{"title":"Submit the communication acknowledgement callback (internal variant) (adapter)","permalink":"/docs/pr-20/docs/nhcx/v1/api/communication/endpoints/communication-internal-v1-communication-on-request"}}'),a=n(62540),o=n(43023),r=n(75064),s=JSON.parse('{"id":"communication_internal_v1_communication_request","module":"Communication","moduleId":"communication","kind":"operation","method":"POST","path":"/internal/v1/communication/request","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"Communication request (internal variant) (adapter)","title":"Submit the communication request (internal variant) (adapter)","description":"Internal twin of /v1/communication/request: same JWEPayload body, description and 202 envelope, operationId communicationRequestPostInternal.\\n\\n### Business purpose\\n\\nSix NHCX services expose each operation twice, once at /v1/... and once at /internal/v1/..., with identical descriptions and request bodies and only the operationId suffix differing. This entry is the internal twin of the payer-initiated communication request: the channel through which a payer pushes TAT alerts, grievances, wallet or policy updates and additional-information requests to a provider. It exists so the exchange can route the same operation over an internal path; the specifications do not document any further difference from the public endpoint.\\n\\n### When to use\\n\\nThe published OpenAPI documents give this path the same semantics as /v1/communication/request: a payer submits a Task plus Communication bundle for a provider during the claim lifecycle, identified by Task.reasonCode (tatquery, grievance, walletupdate, policychange, additionalinfo, claim arbitration). The specs do not state when an integrator should prefer the internal path over the public one, so integrators should code against /v1/communication/request unless onboarding instructions direct otherwise. Header rules are unchanged: request.initiated status and a workflow ID validated against the associated case.\\n\\n### Preconditions\\n\\n- Identical to the public endpoint: registered sender and recipient, valid Bearer token, recipient certificate for JWE encryption (RSA-OAEP-256, A256GCM).\\n- Request body is a JWEPayload, { \\"payload\\": \\"\\" }, whose plaintext is the Task plus Communication collection Bundle.\\n- Protected header carries sender_code, recipient_code, API_call_ID, correlation_ID, workflow_ID, timestamp in IST and status request.initiated.\\n- Whether the internal prefix is reachable from a participant\'s network is not documented; confirm with the environment index and your onboarding contact.\\n\\n### Postconditions\\n\\nReturns the same response set as the public endpoint: 202 Accepted with a StatusSuccessResponse (timestamp, API_call_ID, correlation_ID, result, error), or 400 Request Validation failed, 404 Requested resource was not found and 500 Downstream systems down/unhandled exceptions in the same envelope. The bundle is forwarded to the provider\'s registered callback, which must acknowledge with 202 within 30 seconds and then answer on the communication on_request path under the same correlation ID. No additional state change is documented for the internal variant.\\n\\n### Common mistakes\\n\\n- Assuming the internal path behaves differently or bypasses header validation; the specs describe it as identical apart from the operationId.\\n- Hard-coding the internal prefix in a participant integration without confirmation that it is the route you were onboarded to.\\n- The same envelope errors as the public path: wrong status spelling (NHCX-1011), invalid header (NHCX-1005), duplicate correlation ID (NHCX-1006), invalid workflow (PAYR-1003).\\n- Mixing the hcxsbx.ABDM.gov.in/ spec host and the apisbx.ABDM.gov.in/pmjay/sbxhcx gateway base; a 404 is the first sign.\\n\\n### Best practices\\n\\n- Treat this path exactly as /v1/communication/request in your client: same bundle builder, same header hygiene, same correlation-ID persistence.\\n- Keep the path prefix configurable so you can switch between public and internal forms without a code change.\\n- Use fresh UUIDs for API_call_ID per call and correlation_ID per cycle; use IST timestamps.\\n- Implement v1/error and idempotent callback handling regardless of which path you post to.\\n\\n### Related scenario\\n\\nAn insurer\'s integration team exploring the communicationhcxservice Swagger on the sandbox host sees both communicationRequestPost and communicationRequestPostInternal listed with the same description. They wire their TAT-alert sender to the public /v1/communication/request path as documented in the handbook, keep the internal variant as a configurable alternative, and confirm with NHCX onboarding which form their gateway route expects. The rest of the flow is unchanged: 202 acknowledgement, provider callback within 30 seconds, and the acknowledgement Task on the on_request path.\\n\\n### Specification\\n\\nChapter [Communication](/docs/nhcx/v1/reference/fhir/communication) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"},{"name":"x-hcx-sender_code","required":true,"description":"Your participant code. Mandatory on the envelope.","example":"1518@hcx","type":"string"},{"name":"x-hcx-recipient_code","required":true,"description":"The recipient\'s. For a provider, the processor code from the policy lookup. Mandatory on the envelope.","example":"1000004446@hcx","type":"string"},{"name":"x-hcx-api_call_id","required":true,"description":"Fresh on every message, including responses. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-request_id","required":false,"description":"One per originating request. The Open Protocol page marks it Mandatory; the Technical Specifications page marks it Optional. Optional on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-correlation_id","required":true,"description":"The thread. See the rule below. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-workflow_id","required":false,"description":"Which step, or which case. See the two readings below. Optional on the envelope.","example":"15","type":"string"},{"name":"x-hcx-timestamp","required":true,"description":"See the format note below. Mandatory on the envelope.","example":"<iso timestamp>","type":"string"},{"name":"x-hcx-status","required":true,"description":"Where this message stands. Values below. Mandatory on the envelope.","example":"request.initiated","type":"string"},{"name":"x-hcx-ben-abha-id","required":true,"description":"The beneficiary\'s ABHA number. Mandatory on every exchange, including those with no beneficiary in the payload. Mandatory on the envelope.","example":"91711234567890","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"payload","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"payload":"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxNTE4QGhjeCJ9.encrypted_key.iv.ciphertext.tag"},"responses":[{"status":"200","description":"Returns the same response set as the public endpoint: 202 Accepted with a StatusSuccessResponse (timestamp, api_call_id, correlation_id, result, error), or 400 Request Validation failed, 404 Requested resource was not found and 500 Downstream systems down/unhandled exceptions in the same envelope.","example":{"timestamp":"25/08/2026 12:05:00:412","api_call_id":"c3d4e5f6-a7b8-9012-cdef-123456789012","correlation_id":"22334455-6677-8899-aabb-ccddeeff0011","result":{"sender_code":"1518@hcx","recipient_code":"1000004446@hcx","entity_type":"task","protocol_status":"request.queued"},"error":{"code":"","message":""}}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/internal/v1/communication/request \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: 15\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: request.initiated\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxNTE4QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/internal/v1/communication/request \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: 15\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: request.initiated\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxNTE4QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/hcx/internal/v1/communication/request\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"x-hcx-sender_code\\": \\"1518@hcx\\",\\n        \\"x-hcx-recipient_code\\": \\"1000004446@hcx\\",\\n        \\"x-hcx-api_call_id\\": \\"<uuid>\\",\\n        \\"x-hcx-request_id\\": \\"<uuid>\\",\\n        \\"x-hcx-correlation_id\\": \\"<uuid>\\",\\n        \\"x-hcx-workflow_id\\": \\"15\\",\\n        \\"x-hcx-timestamp\\": \\"<iso timestamp>\\",\\n        \\"x-hcx-status\\": \\"request.initiated\\",\\n        \\"x-hcx-ben-abha-id\\": \\"91711234567890\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxNTE4QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/internal/v1/communication/request\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"x-hcx-sender_code\\": \\"1518@hcx\\",\\n    \\"x-hcx-recipient_code\\": \\"1000004446@hcx\\",\\n    \\"x-hcx-api_call_id\\": \\"<uuid>\\",\\n    \\"x-hcx-request_id\\": \\"<uuid>\\",\\n    \\"x-hcx-correlation_id\\": \\"<uuid>\\",\\n    \\"x-hcx-workflow_id\\": \\"15\\",\\n    \\"x-hcx-timestamp\\": \\"<iso timestamp>\\",\\n    \\"x-hcx-status\\": \\"request.initiated\\",\\n    \\"x-hcx-ben-abha-id\\": \\"91711234567890\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxNTE4QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Submit the communication request (internal variant) (adapter)",sidebar_label:"Submit the communication request (internal variant) (adapter)",sidebar_class_name:"api-method api-method--post",description:"Internal twin of /v1/communication/request: same JWEPayload body, description and 202 envelope, operationId communicationRequestPostInternal.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-communication.yaml",generated:!0},d,h={},u=[];function p(e){return(0,a.jsx)(r.A,{operation:s})}function l(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(p,{...e})}):p(e)}}}]);